-- A compound compares each column under the first arm that DEFINES a
-- collation (multiSelectCollSeq): a plain table column defines BINARY
-- even when undeclared, so a later arm's COLLATE never applies; the
-- rowid and computed expressions define none and defer to later arms.
CREATE TABLE t1(a, b TEXT);
CREATE TABLE t2(id INTEGER PRIMARY KEY, h TEXT COLLATE NOCASE);
INSERT INTO t1 VALUES (' ', 'x'), ('', 'X'), ('A', 'a'), ('a', 'b'), (1, ' ');
INSERT INTO t2 VALUES (1, 'a'), (2, 'X'), (3, ' ');
SELECT a FROM t1 EXCEPT SELECT ~(id COLLATE RTRIM) FROM t2;
SELECT a FROM t1 UNION SELECT h FROM t2;
SELECT a FROM t1 UNION SELECT h FROM t2 ORDER BY 1;
SELECT b FROM t1 INTERSECT SELECT h FROM t2;
SELECT h FROM t2 INTERSECT SELECT b FROM t1;
SELECT id FROM t2 UNION SELECT h FROM t2;
SELECT rowid FROM t1 UNION SELECT h FROM t2;
SELECT count(*) FROM (SELECT a || '' FROM t1 UNION SELECT h FROM t2);
SELECT 'X' UNION SELECT h FROM t2;
SELECT b FROM t1 GROUP BY b UNION SELECT h FROM t2;
SELECT a FROM t1 EXCEPT SELECT a COLLATE RTRIM FROM t1 WHERE a = '';
SELECT a || '' FROM t1 EXCEPT SELECT a COLLATE RTRIM FROM t1 WHERE a = '';
SELECT +a FROM t1 EXCEPT SELECT h FROM t2;
SELECT CAST(a AS TEXT) FROM t1 EXCEPT SELECT h FROM t2;
SELECT x FROM (SELECT a AS x FROM t1) UNION SELECT h FROM t2;
SELECT count(*) FROM (SELECT x FROM (SELECT a || '' AS x FROM t1) UNION SELECT h FROM t2);
SELECT count(*) FROM (SELECT y FROM (SELECT h AS y FROM t2) UNION SELECT a FROM t1);
SELECT count(*) FROM (SELECT y FROM (SELECT h AS y FROM t2) s JOIN t1 ON 1 UNION SELECT a COLLATE BINARY FROM t1);
CREATE VIEW v(z) AS SELECT h FROM t2;
SELECT count(*) FROM (SELECT z FROM v UNION SELECT a FROM t1);
SELECT DISTINCT y FROM (SELECT h AS y FROM t2 UNION ALL SELECT upper(h) FROM t2);
